import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.CPHNBVkq.js";const s="/corbi/screenshots/pulse-feed.png",f=JSON.parse('{"title":"Pulse Feed","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pulse-feed.md","filePath":"guide/pulse-feed.md"}'),r={name:"guide/pulse-feed.md"};function l(h,e,i,u,d,c){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="pulse-feed" tabindex="-1">Pulse Feed <a class="header-anchor" href="#pulse-feed" aria-label="Permalink to &quot;Pulse Feed&quot;">​</a></h1><p>The Pulse feed is the heart of Corbi. It&#39;s a single, scrolling feed of business updates — called <strong>Pulse items</strong> — drawn from the <a href="./channels.html">channels</a> you&#39;ve set up.</p><p><img src="'+s+'" alt="The Pulse feed"></p><h2 id="opening-your-feed" tabindex="-1">Opening your feed <a class="header-anchor" href="#opening-your-feed" aria-label="Permalink to &quot;Opening your feed&quot;">​</a></h2><p>Select <strong>Pulse</strong> in the navigation drawer. Your most recent updates appear first, newest at the top.</p><p>As you scroll down, older items load automatically — there&#39;s no &quot;next page&quot; button. When you reach the bottom, you&#39;ll see <strong>End of feed</strong>.</p><h2 id="filtering-by-channel" tabindex="-1">Filtering by channel <a class="header-anchor" href="#filtering-by-channel" aria-label="Permalink to &quot;Filtering by channel&quot;">​</a></h2><p>At the top of the feed is a <strong>channel selector</strong>. It lets you switch between:</p><ul><li><strong>All channels</strong> — everything from every channel you&#39;ve set up, combined into one feed.</li><li><strong>A single channel</strong> — only the updates from that one channel.</li></ul><p>Select a channel to focus the feed on it, or switch back to view everything together.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Channels are how you control what shows up here. If your feed is too busy or too quiet, adjust your channels rather than the feed itself. See <a href="./channels.html">About Channels</a>.</p></div><h2 id="reading-an-update" tabindex="-1">Reading an update <a class="header-anchor" href="#reading-an-update" aria-label="Permalink to &quot;Reading an update&quot;">​</a></h2><p>Each Pulse item shows the update along with the <strong>category</strong> it belongs to (for example, Sales or Finance) and when it was posted. Select an item to open its full detail.</p><h2 id="when-the-feed-is-empty" tabindex="-1">When the feed is empty <a class="header-anchor" href="#when-the-feed-is-empty" aria-label="Permalink to &quot;When the feed is empty&quot;">​</a></h2><p>There are two empty states you might run into:</p><ul><li><strong>&quot;No Channels Found&quot;</strong> — you haven&#39;t set up any channels yet. Select <strong>Create Channel</strong> to add your first one. See <a href="./channels-create.html">Creating a Channel</a>.</li><li><strong>&quot;Could not find any Pulse Items&quot;</strong> — you have channels, but there&#39;s nothing to show right now. Try selecting a different channel, adjusting a channel&#39;s settings, or checking back later. You can jump straight to <strong>Manage My Channels</strong> from this screen.</li></ul><blockquote><p>📷 <strong>Screenshot:</strong> <em>Empty feed state — coming soon.</em></p></blockquote><h2 id="tips-for-a-useful-feed" tabindex="-1">Tips for a useful feed <a class="header-anchor" href="#tips-for-a-useful-feed" aria-label="Permalink to &quot;Tips for a useful feed&quot;">​</a></h2><ul><li>Start with one or two channels and add more as you learn what&#39;s useful.</li><li>Use a <strong>Narrow</strong> channel scope when a category produces more than you want to read. See <a href="./channels.html#channel-scope">Channel Scope</a>.</li><li>Add <strong>tags</strong> to a channel to focus on specific projects, people, or items. See <a href="./channels.html#channel-tags">Channel Tags</a>.</li></ul>',19)])])}const g=t(r,[["render",l]]);export{f as __pageData,g as default};
